use soroban_sdk::{contract, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Balance(Address),
    TotalSupply,
}

#[contract]
pub struct Vault;

#[contractimpl]
impl Vault {
    pub fn deposit(env: Env, who: Address, amount: i128) {
        who.require_auth();
        let balance: i128 = env
            .storage()
            .persistent()
            .get(&DataKey::Balance(who.clone()))
            .unwrap_or(0);
        let total_supply: i128 = env
            .storage()
            .instance()
            .get(&DataKey::TotalSupply)
            .unwrap_or(0);

        // Neither of these is checked: an amount near i128::MAX traps the call
        // instead of being rejected, and the contract cannot be recovered by
        // withdrawing through the same path.
        env.storage()
            .persistent()
            .set(&DataKey::Balance(who), &(balance + amount));
        env.storage()
            .instance()
            .set(&DataKey::TotalSupply, &(total_supply + amount));
    }
}

