use soroban_sdk::{contract, contracterror, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Balance(Address),
    Cursor,
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    Overrun = 1,
}

#[contract]
pub struct Vault;

#[contractimpl]
impl Vault {
    // The overflow is handled rather than inherited.
    pub fn deposit(env: Env, who: Address, amount: i128) -> Result<(), Error> {
        who.require_auth();
        let balance: i128 = env
            .storage()
            .persistent()
            .get(&DataKey::Balance(who.clone()))
            .unwrap_or(0);
        let new_balance = balance.checked_add(amount).ok_or(Error::Overrun)?;
        env.storage()
            .persistent()
            .set(&DataKey::Balance(who), &new_balance);
        Ok(())
    }

    // A counter is not an amount: the word list does not match `cursor`, so this
    // arithmetic is not the kind of thing this rule is about.
    pub fn advance(env: Env, steps: u32) {
        let mut cursor: u32 = 0;
        for _ in 0..steps {
            cursor = cursor + 1;
        }
        env.storage().instance().set(&DataKey::Cursor, &cursor);
    }
}
